INSERT INTO tx_corporatetemplate_portfolioitems (uid, pid, tstamp, crdate, deleted, hidden, starttime, endtime, sys_language_uid, l10n_parent, parentid, parenttable, sorting, tx_corporatetemplate_categoriesitem, tx_corporatetemplate_descriptionitem, tx_corporatetemplate_fulltitleitem, tx_corporatetemplate_imagesitem, tx_corporatetemplate_shorttitleitem, tx_corporatetemplate_tagsitem, tx_corporatetemplate_thumbnailimage) VALUES
(1, 2, 1548153293, 1548150767, 0, 0, 0, 0, 0, 0, 11, 'tt_content', 1, 2, '<p>Kallo Corn Cakes - Gabriele Galimberti is a documentary/travel photographer whose work has appeared in many international magazines including Newsweek, Le Monde, Geo, La Repubblica, Io Donna and Vanity Fair among others.</p> <p>He&nbsp; was born in Tuscany in 1977 and studied photography at ‘Fondazione Marangoni’ in Florence.&nbsp; In 2002 Gabriele was selected as one of ten emerging young photographers in a competition called&nbsp; ’Giovane Fotografia in Italia’.&nbsp; He simultaneously made his debut as a commercial photographer with his first magazine assignments, and while he continues to be active in the field, his interests have expanded to include documentary/travel photography. In this vein he recently completed an 18-month couch-surfing trip around the world during which he gathered material for a number of photographic projects.</p>', 'Kallo Corn Cakes', 3, 'Kallo', 'Design / Photography', 1),
(2, 2, 1548153293, 1548150767, 0, 0, 0, 0, 0, 0, 11, 'tt_content', 2, 2, '<p>The Inside - Gabriele Galimberti is a documentary/travel photographer whose work has appeared in many international magazines including Newsweek, Le Monde, Geo, La Repubblica, Io Donna and Vanity Fair among others.</p> <p>He&nbsp; was born in Tuscany in 1977 and studied photography at ‘Fondazione Marangoni’ in Florence.&nbsp; In 2002 Gabriele was selected as one of ten emerging young photographers in a competition called&nbsp; ’Giovane Fotografia in Italia’.&nbsp; He simultaneously made his debut as a commercial photographer with his first magazine assignments, and while he continues to be active in the field, his interests have expanded to include documentary/travel photography. In this vein he recently completed an 18-month couch-surfing trip around the world during which he gathered material for a number of photographic projects.</p>', 'The Inside', 3, 'The Inside', 'Design / Photography', 1),
(3, 2, 1548153293, 1548150767, 0, 0, 0, 0, 0, 0, 11, 'tt_content', 3, 1, '<p>Leitberg - Gabriele Galimberti is a documentary/travel photographer whose work has appeared in many international magazines including Newsweek, Le Monde, Geo, La Repubblica, Io Donna and Vanity Fair among others.</p> <p>He&nbsp; was born in Tuscany in 1977 and studied photography at ‘Fondazione Marangoni’ in Florence.&nbsp; In 2002 Gabriele was selected as one of ten emerging young photographers in a competition called&nbsp; ’Giovane Fotografia in Italia’.&nbsp; He simultaneously made his debut as a commercial photographer with his first magazine assignments, and while he continues to be active in the field, his interests have expanded to include documentary/travel photography. In this vein he recently completed an 18-month couch-surfing trip around the world during which he gathered material for a number of photographic projects.</p>', 'Leitberg', 3, 'Leitberg', 'Graphic Design', 1),
(4, 2, 1548153293, 1548153293, 0, 0, 0, 0, 0, 0, 11, 'tt_content', 4, 1, '<p>Fashion Brand - Gabriele Galimberti is a documentary/travel photographer whose work has appeared in many international magazines including Newsweek, Le Monde, Geo, La Repubblica, Io Donna and Vanity Fair among others. &nbsp;He &nbsp;was born in Tuscany in 1977 and studied photography at ‘Fondazione Marangoni’ in Florence. &nbsp;In 2002 Gabriele was selected as one of ten emerging young photographers in a competition called &nbsp;’Giovane Fotografia in Italia’. &nbsp;He simultaneously made his debut as a commercial photographer with his first magazine assignments, and while he continues to be active in the field, his interests have expanded to include documentary/travel photography. In this vein he recently completed an 18-month couch-surfing trip around the world during which he gathered material for a number of photographic projects.</p>', 'Fashion Brand', 3, 'Fashion Brand', 'Design / Illustration', 1),
